from scipy import ndimage
def f(g):
    g=np.array(g); res=[]
    lab,n=ndimage.label(g!=0, structure=np.ones((3,3)))
    for i in range(1,n+1):
        ys,xs=np.where(lab==i)
        sub=g[ys.min():ys.max()+1, xs.min():xs.max()+1].tolist()
        h=len(sub); w=len(sub[0])
        # horizontal iff sorted by column: col_i + w_i < col_next (no vertical overlap of rows matters not)
        res.append((sub,h,w,(ys.min(),xs.min())))
    def checkH(res):
        s=sorted(res,key=lambda t:t[3][1])
        ok=all(s[i][2]+s[i][4]< s[i+1][3][1] for i in range(len(s)-1))
        return ok
    def checkV(res):
        s=sorted(res,key=lambda t:t[3][0])
        ok=all(s[i][1]+s[i][2]<s[i+1][3][0] for i in range(len(s)-1))
        return ok
    if checkH(res):
        s=sorted(res,key=lambda t:t[3][1]); H=max(t[1] for t in s); W=sum(t[1]+t[2]-1 for t in s)
        out=[[0]*W for _ in range(H)]; x=y=0
        for sub,h,w,t in s:
            for j,row_ in enumerate(sub):
                for k,v in enumerate(row_):
                    if v and y+j<H and x+k<W: out[y+j][x+k]=v
            x+=w-1; y+=h-w  # next starts one below
    else:
        s=sorted(res,key=lambda t:t[3][0]); H=max(t[2] for t in s)+len(s); W=max(t[1] for t in s)
        out=[[0]*W for _ in range(H)]; x=y=0
        for sub,h,w,t in s:
            for j,row_ in enumerate(sub):
                for k,v in enumerate(row_):
                    if v and x+k<W and y+j<H: out[x+y][y+k]=v
            x+=w-1; y+=h-w
    return out
